"""Later validators over depot run outputs.

Each vN(entries) -> (passed, measured). An empty input never passes.
"""

# Assumed inclusive range for supplier reliability (spec gives none).
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def v7(entries):
    """Every warehouse stayed within capacity. measured: offending wh names."""
    entries = list(entries)
    if not entries:
        return False, []
    bad = [e["wh"] for e in entries if e["max_units"] > e["capacity"]]
    return not bad, bad


def v8(entries):
    """All expiries were notified. measured: expired [sku, wh, qty] not notified."""
    entries = list(entries)
    if not entries:
        return False, []
    missing = []
    for e in entries:
        notified = {tuple(n) for n in e["notified"]}
        for x in e["expired"]:
            if tuple(x) not in notified:
                missing.append(list(x))
    return not missing, missing


def v9(entries):
    """Every supplier's reliability is within range. measured: offending suppliers."""
    entries = list(entries)
    if not entries:
        return False, []
    bad = [e["supplier"] for e in entries
           if not RELIABILITY_MIN <= e["reliability"] <= RELIABILITY_MAX]
    return not bad, bad
